 "content": "def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Extend each colored diagonal from its existing lower endpoint to the edge.
    for color, dr, dc in ((0,-1,-1),(2,-1,1)):
        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        # endpoint is the marker furthest down and toward the appropriate starting side
        if color==0:
            r,c=max(pts, key=lambda p:(p[0],p[1]))
        else:
